const j = $json || {};
const jobId = (j.jobId || "").trim();
const headline = (j.headline || "").trim();
const mode = j.mode || "generate_background_and_render_text";
const validModes = ["existing_drive_image", "generate_background_and_render_text", "render_from_template"];

if (!jobId) {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "jobId is required for featured image generator." };
}
if (!headline && mode !== "existing_drive_image") {
  return { ok: false, errorCode: "INVALID_INPUT", errorMessage: "headline is required for image generation mode " + mode };
}
if (!validModes.includes(mode)) {
  return { ok: false, errorCode: "INVALID_MODE", errorMessage: "mode must be one of: " + validModes.join(", ") };
}

return {
  jobId,
  mode,
  headline,
  subheadline: j.subheadline || "",
  driveFileId: j.driveFileId || null,
  ok: true
};

const p = $("02 Validate Parameters").item.json;
const mode = p.mode;

function escapeXml(str) {
  if (!str) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

const h = escapeXml(p.headline);
const sub = escapeXml(p.subheadline);
const width = 1200;
const height = 630;
let svgContent = "";

if (mode === "existing_drive_image") {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="#0f172a"/>
  <rect width="100%" height="100%" fill="rgba(15,23,42,0.75)"/>
  <rect x="50" y="50" width="1100" height="530" fill="none" stroke="#38bdf8" stroke-width="2" rx="16"/>
  <text x="80" y="280" fill="#ffffff" font-family="sans-serif" font-size="48" font-weight="bold">${h}</text>
  <text x="80" y="360" fill="#94a3b8" font-family="sans-serif" font-size="28">${sub}</text>
  <text x="1070" y="110" fill="#38bdf8" font-family="sans-serif" font-size="24" font-weight="bold" text-anchor="end">Mohamed Arslan</text>
</svg>`;
} else if (mode === "render_from_template") {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <linearGradient id="cardGrad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#1e1b4b"/>
      <stop offset="100%" stop-color="#0f172a"/>
    </linearGradient>
  </defs>
  <rect width="100%" height="100%" fill="url(#cardGrad)"/>
  <rect x="40" y="40" width="1120" height="550" fill="#1e293b" fill-opacity="0.6" stroke="#6366f1" stroke-width="3" rx="20"/>
  <rect x="80" y="80" width="240" height="48" fill="#6366f1" rx="8"/>
  <text x="200" y="112" fill="#ffffff" font-family="sans-serif" font-size="20" font-weight="bold" text-anchor="middle">MOHAMED ARSLAN</text>
  <text x="80" y="260" fill="#ffffff" font-family="sans-serif" font-size="52" font-weight="bold">${h}</text>
  <text x="80" y="340" fill="#cbd5e1" font-family="sans-serif" font-size="28">${sub}</text>
  <line x1="80" y1="440" x2="1040" y2="440" stroke="#334155" stroke-width="2"/>
  <text x="80" y="490" fill="#818cf8" font-family="sans-serif" font-size="22">Content Automation Engine</text>
</svg>`;
} else {
  svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <defs>
    <linearGradient id="bgGrad" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#0f172a"/>
      <stop offset="50%" stop-color="#1e293b"/>
      <stop offset="100%" stop-color="#0369a1"/>
    </linearGradient>
  </defs>
  <rect width="100%" height="100%" fill="url(#bgGrad)"/>
  <rect x="60" y="60" width="1080" height="510" fill="none" stroke="#0284c7" stroke-width="4" rx="16"/>
  <text x="100" y="270" fill="#ffffff" font-family="sans-serif" font-size="48" font-weight="bold">${h}</text>
  <text x="100" y="350" fill="#bae6fd" font-family="sans-serif" font-size="26">${sub}</text>
  <text x="1040" y="120" fill="#38bdf8" font-family="sans-serif" font-size="24" font-weight="bold" text-anchor="end">Mohamed Arslan</text>
</svg>`;
}

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: "featured-main",
    assetType: "featured_image",
    generatorMode: mode,
    width,
    height,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: "featured-main.svg",
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    json: {
      success: false,
      jobId: meta.jobId || null,
      status: "FAILED",
      message: "Featured image generation failed — no binary image output produced.",
      data: null,
      warnings: [],
      errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Image renderer did not produce binary output data." }],
      nextAllowedActions: ["retry", "cancel"]
    },
    binary: item.binary
  };
}

const norm = {
  success: true,
  jobId: meta.jobId,
  status: "ASSET_GENERATED",
  message: "Featured image binary generated successfully using mode: " + meta.generatorMode,
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    generatorMode: meta.generatorMode,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

return {
  json: norm,
  binary: item.binary
};

const j = $json || {};
const code = j.errorCode || "INVALID_INPUT";
const message = j.errorMessage || "Invalid input parameters for featured image generator.";
return {
  json: {
    success: false,
    jobId: j.jobId || null,
    status: "FAILED",
    message,
    data: null,
    warnings: [],
    errors: [{ code, language: null, path: null, message }],
    nextAllowedActions: ["cancel"]
  },
  binary: $input.item ? $input.item.binary : undefined
};
